$ErrorActionPreference='Stop';$utf8=[Text.UTF8Encoding]::new($false);$fixture=Join-Path ([IO.Path]::GetTempPath()) ('et-secret-lease-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory $fixture|Out-Null
try{$keys=@{};foreach($name in @('lease','release')){$rsa=[Security.Cryptography.RSA]::Create(3072);try{$private=Join-Path $fixture "$name.private.pem";$public=Join-Path $fixture "$name.public.pem";[IO.File]::WriteAllText($private,$rsa.ExportPkcs8PrivateKeyPem(),$utf8);[IO.File]::WriteAllText($public,$rsa.ExportSubjectPublicKeyInfoPem(),$utf8);$keys[$name]=@{Private=$private;Public=$public}}finally{$rsa.Dispose()}};. "$PSScriptRoot/BackupRestore.Common.ps1"
    $root=Join-Path $fixture 'secret-root';New-Item -ItemType Directory $root|Out-Null;$mongo=Join-Path $root 'mongo-uri';$token=Join-Path $root 'metrics-token';[IO.File]::WriteAllText($mongo,'mongodb://test:secret@db/?tls=true',$utf8);[IO.File]::WriteAllText($token,[Convert]::ToHexString([Security.Cryptography.RandomNumberGenerator]::GetBytes(32)),$utf8)
    $created=(((& "$PSScriptRoot/New-SecretLease.ps1" -LeaseId lease-test -DeploymentId deployment-test -Provider test-secret-agent -Generation 1 -ValidityMinutes 60 -SecretRoot $root -SecretFiles $mongo,$token -SigningPrivateKeyFile $keys.lease.Private -SigningKeyId lease-signer -ReleaseSigningPublicKeyFile $keys.release.Public -OutputDirectory (Join-Path $root 'leases'))-join[Environment]::NewLine)|ConvertFrom-Json);$v=@{LeaseFile=$created.LeaseFile;SignatureFile=$created.SignatureFile;TrustedPublicKeyFile=$keys.lease.Public;ExpectedSigningKeyId='lease-signer';ReleaseSigningPublicKeyFile=$keys.release.Public;ExpectedDeploymentId='deployment-test';SecretRoot=$root};& "$PSScriptRoot/Test-SecretLease.ps1" @v|Out-Null
    [IO.File]::AppendAllText($mongo,'tamper');$rejected=$false;try{& "$PSScriptRoot/Test-SecretLease.ps1" @v|Out-Null}catch{$rejected=$true};if(-not$rejected){throw 'Changed leased Secret was accepted'}
    $wrong=$v.Clone();$wrong.ExpectedDeploymentId='other-deployment';$rejected=$false;try{& "$PSScriptRoot/Test-SecretLease.ps1" @wrong|Out-Null}catch{$rejected=$true};if(-not$rejected){throw 'Cross-deployment lease was accepted'}
    $badRoot=Join-Path $fixture 'reuse-root';New-Item -ItemType Directory $badRoot|Out-Null;$badSecret=Join-Path $badRoot 'secret';[IO.File]::WriteAllText($badSecret,'value',$utf8);$rejected=$false;try{& "$PSScriptRoot/New-SecretLease.ps1" -LeaseId reused -DeploymentId deployment-test -Provider test -Generation 1 -ValidityMinutes 60 -SecretRoot $badRoot -SecretFiles $badSecret -SigningPrivateKeyFile $keys.release.Private -SigningKeyId reused -ReleaseSigningPublicKeyFile $keys.release.Public -OutputDirectory (Join-Path $badRoot 'leases')|Out-Null}catch{$rejected=$true};if(-not$rejected){throw 'Release signing key was reused for Secret lease'}
    $largeRoot=Join-Path $fixture 'large-root';New-Item -ItemType Directory $largeRoot|Out-Null;$largeSecret=Join-Path $largeRoot 'secret';[IO.File]::WriteAllBytes($largeSecret,[byte[]]::new(1MB+1));$rejected=$false;try{& "$PSScriptRoot/New-SecretLease.ps1" -LeaseId too-large -DeploymentId deployment-test -Provider test -Generation 1 -ValidityMinutes 60 -SecretRoot $largeRoot -SecretFiles $largeSecret -SigningPrivateKeyFile $keys.lease.Private -SigningKeyId lease-signer -ReleaseSigningPublicKeyFile $keys.release.Public -OutputDirectory (Join-Path $largeRoot 'leases')|Out-Null}catch{$rejected=$true};if(-not$rejected){throw 'Oversized Secret was accepted'}
    [ordered]@{Passed=$true;SignedLeaseVerified=$true;TwoSecretsBound=$true;SecretTamperRejected=$true;CrossDeploymentRejected=$true;OversizedSecretRejected=$true;ReleaseKeyReuseRejected=$true}|ConvertTo-Json
}finally{$temp=[IO.Path]::GetFullPath([IO.Path]::GetTempPath()).TrimEnd('\','/')+[IO.Path]::DirectorySeparatorChar;$resolved=[IO.Path]::GetFullPath($fixture);if($resolved.StartsWith($temp,[StringComparison]::OrdinalIgnoreCase)-and[IO.Path]::GetFileName($resolved)-match'^et-secret-lease-[a-f0-9]{32}$'-and(Test-Path $resolved)){Remove-Item $resolved -Recurse -Force}}
